const STORAGE_KEY="elu-live-state-v2";
const STORAGE_VERSION=3;
const SESSION_KEY="elu-demo-student-id";

function migrateState(raw={}){
 const base=seedState(),next={...base,...raw,schemaVersion:STORAGE_VERSION};
 next.students=base.students.map(fallback=>{const saved=(raw.students||[]).find(s=>s.id===fallback.id)||{};return {...fallback,...saved,inventory:Array.isArray(saved.inventory)?saved.inventory:[],transactions:Array.isArray(saved.transactions)?saved.transactions:[],history:Array.isArray(saved.history)?saved.history:[],stickers:Array.isArray(saved.stickers)?saved.stickers:[]}});
 next.completions=Object.fromEntries(base.students.map(s=>[s.id,Array.isArray(raw.completions?.[s.id])?raw.completions[s.id]:[]]));
 next.weekRecords=Object.fromEntries(base.students.map(s=>[s.id,weeks.map((w,index)=>({...base.weekRecords[s.id][index],...(raw.weekRecords?.[s.id]?.[index]||{}),week:w.number}))]));
 next.submissions=Object.fromEntries(base.students.map(s=>[s.id,{...(raw.submissions?.[s.id]||{})}]));
 delete next.previewId;delete next.viewerId;delete next["cursor"+"Enabled"];
 return next;
}

const LocalDemoStore={
 load(){try{const saved=localStorage.getItem(STORAGE_KEY);return saved?migrateState(JSON.parse(saved)):seedState()}catch(error){console.warn("State could not be loaded",error);return seedState()}},
 save(next){localStorage.setItem(STORAGE_KEY,JSON.stringify({...next,schemaVersion:STORAGE_VERSION}))},
 getCurrentStudent(next,id){return next.students.find(student=>student.id===id)||next.students[0]},
 getStudents(next){return next.students},
 updateStudent(next,id,patch){Object.assign(next.students.find(student=>student.id===id),patch)},
 addXpTransaction(next,id,transaction){next.students.find(student=>student.id===id).transactions.push(transaction)},
 grantReward(next,id,rewardId){const student=next.students.find(item=>item.id===id);if(student.inventory.includes(rewardId))return false;student.inventory.push(rewardId);return true},
 updateMission(next,id,patch){const mission=next.missions.find(item=>item.id===id);if(mission)Object.assign(mission,patch);else next.missions.push(patch)},
 saveSubmission(next,id,week,value,type){next.submissions[id]??={};next.submissions[id][week]={value,type,status:"Submitted",submittedAt:new Date().toISOString()}}
};

let state=LocalDemoStore.load();
let route="home";
let adminTab="tracker";
let lastUndo=null;
let uploadDraft=null;
let selectedMissionWeek=state.currentWeek;
let adminPreviewStudentId=null;
let activeStudentDrawer=null;
let overlayReturnDrawer=null;
let overlayOpener=null;
