const navItems=[
  ["home","Главная","i-home"],["challenge","Челлендж","i-zap"],["missions","Миссии","i-target"],["crew","Команда","i-users"],
  ["events","События","i-calendar"],["feed","Лента","i-message"],["leaderboard","Рейтинг","i-trophy"],["profile","Профиль","i-user"]
];

function saveState(){try{LocalDemoStore.save(state)}catch(e){toast("Хранилище заполнено. Уменьшите фото.")}}
function escapeHtml(value=""){return String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function assetById(id){return assets.find(a=>a.id===id)}
function studentById(id){return state.students.find(s=>s.id===id)}
function totalXp(student){return student.transactions.reduce((sum,t)=>sum+Number(t.amount),0)}
function completedCount(student){return (state.completions[student.id]||[]).length}
function rankedStudents(){return [...state.students].sort((a,b)=>totalXp(b)-totalXp(a)||completedCount(b)-completedCount(a)||a.name.localeCompare(b.name,"ru"))}
function rankFor(student){if(!hasLeaderboardStarted()||totalXp(student)<=0)return null;return 1+state.students.filter(other=>totalXp(other)>totalXp(student)).length}
function crewPower(){return state.students.reduce((sum,s)=>sum+totalXp(s),0)}
function currentStudent(){return LocalDemoStore.getCurrentStudent(state,currentStudentId)}
function viewer(){return adminPreviewStudentId?studentById(adminPreviewStudentId):currentStudent()}
function isPreviewMode(){return Boolean(adminPreviewStudentId)}
function isAdminMode(){return route==="admin"&&!isPreviewMode()}
function requireAdminMutation(){if(isAdminMode())return true;toast("Изменения доступны только в Admin demo");return false}
function effectsOn(){return state.effectsMode!=="off"}
function fullEffects(){return state.effectsMode==="full"}
function hasXp(student){return totalXp(student)!==0}
function hasRewards(student){return student.inventory.length>0}
function hasMissionProgress(student){return student.progress>0||student.weekStatus!=="Not Started"}
function hasSeasonActivity(){return state.students.some(student=>hasXp(student)||hasRewards(student)||hasMissionProgress(student))}
function hasLeaderboardStarted(){return state.students.some(student=>totalXp(student)>0)}
function addHistory(student,action,detail){student.history.unshift({action,detail,time:new Date().toISOString()});student.history=student.history.slice(0,80)}
function avatarHtml(s,size=""){return `<span class="avatar ${size}" style="--accent:${s.accent}">${s.photo?`<img src="${s.photo}" alt="Фото ${escapeHtml(s.name)}">`:escapeHtml(s.initial)}</span>`}
function icon(id){return `<svg class="ui-icon" aria-hidden="true" focusable="false"><use href="#${id}"/></svg>`}
function fmt(n){return new Intl.NumberFormat("ru-RU").format(n)}
function clamp(n,min,max){return Math.min(max,Math.max(min,n))}
function statusLabel(value){return ({active:"Активна",locked:"Закрыто",completed:"Выполнено",available:"Доступно","Not Started":"Не начато","In Progress":"В процессе",Submitted:"На проверке","Needs Revision":"Нужна доработка",Completed:"Выполнено",Locked:"Закрыто"})[value]||value}
function assetImg(asset,loading="lazy",className=""){return `<span class="asset-visual ${className}" style="--tone:${asset.tone}"><img src="${asset.image}" alt="${asset.name}" loading="${loading}" width="220" height="220" data-fallback><span class="image-fallback" aria-hidden="true">${asset.name.slice(0,1)}</span></span>`}
function applyTheme(){document.documentElement.dataset.theme=theme;localStorage.setItem(THEME_KEY,theme);document.querySelectorAll(".theme-toggle").forEach(button=>{button.setAttribute("aria-pressed",String(theme==="light"));button.title=theme==="light"?"Включить тёмную тему":"Включить светлую тему";const mark=button.querySelector("span");if(mark)mark.textContent=theme==="light"?"☾":"☀"});const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=theme==="light"?"#eef2ff":"#111a46"}

function renderNav(){
  const main=document.querySelector("#mainNav"),bottom=document.querySelector("#bottomNav");
  main.innerHTML=navItems.map(([id,label,ico])=>`<button class="nav-button ${route===id?"active":""}" data-route="${id}">${icon(ico)}<span>${label}</span></button>`).join("");
  const mobile=navItems.filter(x=>["home","challenge","missions","crew","profile"].includes(x[0]));
  bottom.innerHTML=mobile.map(([id,label,ico])=>`<button class="nav-button ${route===id?"active":""}" data-route="${id}">${icon(ico)}<span>${label}</span></button>`).join("");
}

function renderChrome(){
  const s=viewer();
  document.querySelector("#miniProfile").innerHTML=`${avatarHtml(s)}<span><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.nickname)}</small></span>`;
  document.querySelector("#headerAvatar").innerHTML=s.photo?`<img src="${s.photo}" alt="${escapeHtml(s.name)}">`:escapeHtml(s.initial);
  document.querySelector("#headerXp").textContent=fmt(totalXp(s));document.querySelector("#headerStreak").textContent=s.streak;
  document.querySelector("#xpPill").title=`XP: ${fmt(totalXp(s))}`;document.querySelector("#streakPill").title=`Стрик: ${s.streak} ${pluralDays(s.streak)}`;applyTheme();
  const banner=document.querySelector("#previewBanner");
  if(isPreviewMode()){banner.classList.remove("hidden");banner.innerHTML=`ПРОСМОТР КАК <strong>${escapeHtml(s.name).toUpperCase()}</strong><button data-action="exit-preview">Вернуться в Admin</button>`}else banner.classList.add("hidden");
}

function go(next){route=next;const target=next==="home"?new URL(".",APP_BASE):new URL(`#${next}`,APP_BASE);history.replaceState(null,"",target);render()}
function render(){renderNav();renderChrome();applyPreferences();const view=document.querySelector("#view");const renderer={home:renderHome,challenge:renderChallenge,missions:renderMissions,crew:renderCrew,events:renderEvents,leaderboard:renderLeaderboard,feed:renderFeed,profile:renderProfile,admin:renderAdmin}[route]||renderHome;view.innerHTML=`<div class="page-enter">${renderer()}</div>`;view.focus({preventScroll:true});requestAnimationFrame(setupEnhancements)}

function weekState(w){if((state.completions[viewer().id]||[]).includes(w.number))return "completed";if(w.number===state.currentWeek)return "active";if(w.number>state.currentWeek)return "locked";return "available"}
function roadmapHtml(){return `<div class="roadmap">${weeks.map(w=>{const a=assetById(w.asset),st=weekState(w),locked=st==="locked";return `<button class="week-card mechanic-${w.asset} ${st}" style="--theme:${w.tone}" data-action="view-week" data-week="${w.number}" ${locked?'disabled aria-disabled="true"':''} aria-label="Неделя ${w.number}: ${w.title}, ${statusLabel(st)}"><small>WEEK ${w.number}</small>${assetImg(a)}<strong>${w.title}</strong><span>${a.name} · ${statusLabel(st)}</span></button>`}).join("")}</div>`}

function studentCard(s){const xp=totalXp(s),rank=rankFor(s);return `<article class="student-card tilt-card student-card-readonly" style="--accent:${s.accent}" aria-label="Участник ${escapeHtml(s.name)}">${rank?`<div class="rank">${rank}</div>`:""}<div class="student-top">${avatarHtml(s)}<div class="student-name"><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.nickname)}</small></div></div><div class="badgeline"><span class="level-chip">B1 · Level ${s.level}</span><span class="xp-label" data-counter="${xp}">${fmt(xp)} XP</span></div><div class="streak ${s.streak>0?'is-live':''}">Стрик: ${s.streak} ${pluralDays(s.streak)}${s.streak>0?' 🔥':''}</div><div class="progress-label"><span>Week ${state.currentWeek} · ${statusLabel(s.weekStatus)}</span><b>${s.progress}%</b></div><div class="progress" style="--progress:${s.progress}%"><i></i></div><div class="sticker-row">${s.stickers.length?s.stickers.slice(0,3).map((x,i)=>`<span class="sticker" style="--rot:${i%2?2:-2}deg">${escapeHtml(x)}</span>`).join(""):'<span class="empty-chip">Наград пока нет</span>'}</div></article>`}
function pluralDays(n){const d=n%10;return d===1?"день":d>1&&d<5?"дня":"дней"}
function sectionHead(title,sub="",action=""){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:""}</div>${action}</div>`}
function leaderList(compact=true){if(!hasLeaderboardStarted())return `<div class="zero-state leaderboard-zero"><span>✦</span><strong>ВСЕ НАЧИНАЮТ С ОДНОЙ ПОЗИЦИИ</strong><small>Рейтинг появится после первых XP</small></div>`;return rankedStudents().map(s=>`<div class="leader-row ${rankFor(s)===1?'leader-first':''} ${compact?'leader-compact':''}"><i>${rankFor(s)||'—'}</i>${compact?'':avatarHtml(s)}<span><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.featuredBadge||statusLabel(s.weekStatus))}</small></span><b>${fmt(totalXp(s))} XP</b></div>`).join("")}
function feedList(limit=9){if(!state.feed.length)return `<div class="zero-state"><span>⚡</span><strong>Сезон только начинается</strong><small>Первые события появятся здесь</small></div>`;return state.feed.slice(0,limit).map(f=>`<div class="feed-item reveal"><span class="feed-icon">${f.icon}</span><span>${escapeHtml(f.text)}</span><time>${escapeHtml(f.time)}</time></div>`).join("")}

function renderHome(){
 const s=viewer(),w=weeks[state.currentWeek-1],crew=crewPower(),pct=clamp(crew/state.crewGoal*100,0,100),earned=s.inventory.slice(0,4);
 return `<section class="hero animated-stage" style="--hero-image:url('${HERO_ASSET}')"><div class="hero-media"><div class="hero-poster" role="img" aria-label="Неоновая фестивальная сцена и зрители"></div><div class="stage-vignette"></div><i class="light-beam beam-one"></i><i class="light-beam beam-two"></i><i class="light-beam beam-three"></i><div class="hero-particles" aria-hidden="true">${Array.from({length:16},(_,i)=>`<i style="--i:${i}"></i>`).join("")}</div><div class="hero-doodles" aria-hidden="true"><b>⚡</b><b>♕</b><b>★</b><b>♫</b><b>➜</b></div></div><div class="hero-copy"><div class="eyebrow hero-eyebrow">8-недельный челлендж B1</div><h1><span class="hero-english">English</span><br><span class="lime hero-level">Level Up</span></h1><div class="hero-tagline">Speak. Learn. Shine.</div><div class="hero-sub hero-subtitle"><span>Week ${w.number} · ${w.title}</span><span>${escapeHtml(state.seasonDates)}</span></div><div class="hero-actions"><button class="btn btn-primary cta-live" data-action="open-current-mission">▶ ОТКРЫТЬ МИССИЮ</button><button class="btn btn-secondary" data-route="challenge">Смотреть roadmap →</button></div></div></section>
 ${sectionHead("Твой путь к Main Stage","8 недель · 8 механик · один crew","<button class='link-button' data-route='challenge'>Все недели →</button>")}${roadmapHtml()}
 <div class="dashboard-grid"><div class="content-stack">${sectionHead("Crew ready","Четыре участника · карточки доступны только для просмотра")}<div class="student-grid">${state.students.map(studentCard).join("")}</div><article class="panel mission-card" style="--mission-asset:url('${assetById(w.asset).image}')"><div class="eyebrow">⚡ Текущая неделя</div><div class="mission-title">Week ${w.number} — ${w.title}</div><div class="mission-main"><small>ГЛАВНАЯ МИССИЯ</small><strong>${w.mission}</strong></div><div class="mission-rewards"><div class="reward-box"><b>SECRET BONUS +${w.bonusXp} XP</b>${w.bonus}</div><div class="reward-box"><b>НАГРАДА +${w.xp} XP</b>${assetById(w.asset).name}</div></div><button class="btn btn-primary cta-live" data-action="open-current-mission">Открыть миссию ⚡</button></article>
 <div class="feed-grid"><article class="panel collection-preview"><h3>Моя коллекция</h3>${earned.length?`<div class="asset-strip">${earned.map(id=>{const a=assetById(id);return `<button class="asset-mini" data-asset="${a.id}">${assetImg(a)}<span>${a.name}</span></button>`}).join("")}</div>`:`<div class="zero-state compact"><span>◇</span><strong>Первые награды ещё впереди</strong><small>Они появятся после выполнения миссий</small></div>`}<button class="link-button" data-route="profile">Все награды в профиле →</button></article><article class="panel"><h3>Лента команды</h3><div class="feed-list">${feedList(3)}</div></article></div></div>
 <aside class="side-stack"><article class="panel crew-panel"><h3>⚡ Crew Power</h3><div class="crew-number">${fmt(crew)} <small>/ ${fmt(state.crewGoal)} XP</small></div><div class="milestones"><span>0</span><span>5K</span><span>10K</span><span>15K</span><span>20K</span></div><div class="progress crew-progress" style="--progress:${pct}%"><i></i></div><p>Заполняйте шкалу всей командой и открывайте общий бонус.</p></article><article class="panel event-card"><div class="eyebrow">● UPCOMING</div><h3>Season Kickoff</h3><div class="event-row"><span class="event-icon">🎟️</span><div><strong>First Ticket</strong><small>Дата будет объявлена</small></div></div></article>${state.leaderboardEnabled?`<article class="panel"><h3>🏆 Рейтинг</h3><div class="leader-list">${leaderList()}</div></article>`:""}</aside></div>`
}

function pageHeader(title,sub,action=""){return `<div class="page-header"><div><h1 class="page-title">${title}</h1><p>${sub}</p></div>${action}</div>`}
function renderChallenge(){return `${pageHeader("8-week challenge","Восемь недель · восемь наград · один Main Stage")}<div class="challenge-grid">${weeks.map(w=>{const a=assetById(w.asset),st=weekState(w);return `<article class="week-card big-week mechanic-${w.asset} ${st}" style="--theme:${w.tone}"><span class="state-label">${st==="locked"?'🔒 ':st==="completed"?'✓ ':''}${statusLabel(st)}</span><small>WEEK ${w.number}</small>${assetImg(a)}<h3>${w.title}</h3><p>${w.mission}</p><div class="week-reward">Награда: +${w.xp} XP · ${a.name}</div><button class="btn ${st==="locked"?"btn-secondary":"btn-primary"} btn-compact" ${st==="locked"?"disabled":""} data-action="view-week" data-week="${w.number}">${st==="locked"?"Неделя закрыта":"Открыть миссию →"}</button></article>`}).join("")}</div>`}
function renderMissions(){
 const student=viewer(),week=selectedMissionWeek||state.currentWeek,w=weeks[week-1],mission=state.missions.find(item=>item.week===week)||{instructions:w.bonus,submissionType:"link"},record=state.weekRecords[student.id][week-1],submission=state.submissions[student.id]?.[week];
 const canEdit=!isPreviewMode()&&["In Progress","Needs Revision"].includes(record.status),supported=["text","link"].includes(mission.submissionType);
 const cta=record.status==="Not Started"?`<button class="btn btn-primary cta-live" data-action="start-mission" data-week="${week}">▶ НАЧАТЬ МИССИЮ</button>`:record.status==="In Progress"||record.status==="Needs Revision"?`<button class="btn btn-primary cta-live" data-action="continue-mission">ПРОДОЛЖИТЬ МИССИЮ →</button>`:`<button class="btn btn-secondary" disabled>${record.status==="Submitted"?"НА ПРОВЕРКЕ":"МИССИЯ ВЫПОЛНЕНА"}</button>`;
 const submissionControl=supported?(mission.submissionType==="link"?`<input class="form-control" id="submissionValue" type="url" placeholder="https://…" value="${escapeHtml(submission?.value||'')}" ${canEdit?'':'disabled'}>`:`<textarea class="form-control" id="submissionValue" placeholder="Напиши ответ здесь" ${canEdit?'':'disabled'}>${escapeHtml(submission?.value||'')}</textarea>`):`<div class="settings-note"><b>DEMO</b><span>Тип «${escapeHtml(mission.submissionType)}» требует production backend. Fake upload не используется.</span></div>`;
 return `${pageHeader(`Week ${w.number} · ${w.title}`,"Mission detail · статус и отправка задания")}<div class="dashboard-grid mission-detail"><div class="content-stack"><article class="panel mission-card" style="--mission-asset:url('${assetById(w.asset).image}')"><div class="eyebrow">STATUS · ${statusLabel(record.status)}</div><div class="mission-title">${w.title}</div><div class="mission-main"><small>ГЛАВНАЯ МИССИЯ</small><strong>${w.mission}</strong></div><div class="mission-rewards"><div class="reward-box"><b>ИНСТРУКЦИЯ</b>${escapeHtml(mission.instructions||w.bonus)}</div><div class="reward-box"><b>SECRET BONUS +${w.bonusXp} XP</b>${w.bonus}</div><div class="reward-box"><b>НАГРАДА ПОСЛЕ ПРОВЕРКИ</b>${assetById(w.asset).name} · +${w.xp} XP</div></div>${isPreviewMode()?'<span class="info-chip">Preview · read only</span>':cta}</article><article class="panel submission-panel" id="submissionPanel"><h3>Отправка задания</h3><p>Тип: <strong>${escapeHtml(mission.submissionType)}</strong>. После отправки статус изменится на «На проверке».</p>${submissionControl}${canEdit&&supported?`<button class="btn btn-primary" data-action="submit-mission" data-week="${week}">ОТПРАВИТЬ НА ПРОВЕРКУ</button>`:""}${submission?`<small>Отправлено: ${new Date(submission.submittedAt).toLocaleString('ru-RU')}</small>`:""}</article></div><aside class="panel mission-status-panel"><h3>Твой статус</h3><strong class="mission-status-value">${statusLabel(record.status)}</strong><div class="stat-card"><span>Прогресс</span><strong style="--tone:${student.accent}">${record.progress}%</strong><div class="progress" style="--progress:${record.progress}%"><i></i></div></div>${student.feedback?`<div class="teacher-feedback"><small>КОММЕНТАРИЙ ПРЕПОДАВАТЕЛЯ</small><p>${escapeHtml(student.feedback)}</p></div>`:""}<p>XP и награды выдаёт преподаватель после проверки. Начало миссии не начисляет XP.</p></aside></div>`
}
function renderCrew(){const crew=crewPower(),pct=clamp(crew/state.crewGoal*100,0,100);return `${pageHeader("Crew Power","Level up together · поддержка тоже считается")}<div class="stats-grid"><div class="stat-card"><span>Участников</span><strong>4</strong></div><div class="stat-card"><span>Всего XP</span><strong>${fmt(crew)}</strong></div><div class="stat-card"><span>Миссий закрыто</span><strong>${Object.values(state.completions).flat().length}</strong></div><div class="stat-card"><span>Crew goal</span><strong>${Math.round(pct)}%</strong></div></div>${sectionHead("Участники","Crew Token выдаётся за реальный вклад")}<div class="student-grid">${rankedStudents().map(studentCard).join("")}</div>${sectionHead("Crew milestones")}<article class="panel crew-panel"><div class="crew-number">${fmt(crew)} <small>/ ${fmt(state.crewGoal)} XP</small></div><div class="progress" style="--progress:${pct}%"><i></i></div><div class="milestones" style="font-size:11px"><span>5K · Sticker pack</span><span>10K · Access Key</span><span>15K · Secret Event</span><span>20K · Crew Drop</span></div></article>`}
function renderEvents(){return `${pageHeader("Live events","События сезона и путь к Main Stage")}<div class="events-grid">${state.events.map((e,i)=>`<article class="panel event-card"><div class="event-row"><span class="event-icon">${e.icon}</span><div><div class="eyebrow">${e.status}</div><h2>${escapeHtml(e.title)}</h2><small>${escapeHtml(e.date)}</small></div></div><p>Награда · ${escapeHtml(e.reward)}</p>${i===0?`<button class="btn btn-primary btn-compact" data-action="event-info" data-id="${e.id}">Подробнее</button>`:`<span class="info-chip">🔒 Закрыто</span>`}</article>`).join("")}</div>`}
